CREATE TABLE branch_protections (repo_id TEXT NOT NULL REFERENCES repositories(id) ON DELETE CASCADE, branch TEXT NOT NULL, require_mr INTEGER NOT NULL DEFAULT 1, approvals INTEGER NOT NULL DEFAULT 1 CHECK(approvals BETWEEN 0 AND 10), require_ci INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(repo_id,branch));
CREATE TABLE merge_reviews (id INTEGER PRIMARY KEY AUTOINCREMENT, mr_id INTEGER NOT NULL REFERENCES merge_requests(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id), source_sha TEXT NOT NULL, target_sha TEXT NOT NULL, verdict TEXT NOT NULL CHECK(verdict IN ('approve','changes','comment')), body TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX merge_reviews_mr ON merge_reviews(mr_id,id);
CREATE TABLE labels (id TEXT PRIMARY KEY, repo_id TEXT NOT NULL REFERENCES repositories(id) ON DELETE CASCADE, name TEXT NOT NULL, color TEXT NOT NULL DEFAULT '64748b', UNIQUE(repo_id,name));
CREATE TABLE milestones (id TEXT PRIMARY KEY, repo_id TEXT NOT NULL REFERENCES repositories(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', due_date TEXT, state TEXT NOT NULL DEFAULT 'open' CHECK(state IN ('open','closed')));
ALTER TABLE issues ADD COLUMN assignee_id TEXT REFERENCES users(id) ON DELETE SET NULL;
ALTER TABLE issues ADD COLUMN milestone_id TEXT REFERENCES milestones(id) ON DELETE SET NULL;
CREATE TABLE issue_labels (issue_id INTEGER NOT NULL REFERENCES issues(id) ON DELETE CASCADE, label_id TEXT NOT NULL REFERENCES labels(id) ON DELETE CASCADE, PRIMARY KEY(issue_id,label_id));
CREATE TABLE releases (id TEXT PRIMARY KEY, repo_id TEXT NOT NULL REFERENCES repositories(id) ON DELETE CASCADE, tag TEXT NOT NULL, sha TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL DEFAULT '', prerelease INTEGER NOT NULL DEFAULT 0, author_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE(repo_id,tag));
CREATE TABLE deployments (id TEXT PRIMARY KEY, repo_id TEXT NOT NULL REFERENCES repositories(id) ON DELETE CASCADE, run_id TEXT NOT NULL REFERENCES ci_runs(id) ON DELETE CASCADE, environment TEXT NOT NULL, sha TEXT NOT NULL, object_key TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE environments (repo_id TEXT NOT NULL REFERENCES repositories(id) ON DELETE CASCADE, name TEXT NOT NULL, deployment_id TEXT REFERENCES deployments(id) ON DELETE SET NULL, public INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL DEFAULT (datetime('now')), PRIMARY KEY(repo_id,name));
CREATE TABLE wiki_pages (repo_id TEXT NOT NULL REFERENCES repositories(id) ON DELETE CASCADE, slug TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, author_id TEXT NOT NULL REFERENCES users(id), updated_at TEXT NOT NULL DEFAULT (datetime('now')), PRIMARY KEY(repo_id,slug));
CREATE TABLE wiki_history (repo_id TEXT NOT NULL REFERENCES repositories(id) ON DELETE CASCADE, slug TEXT NOT NULL, version INTEGER NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, author_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (datetime('now')), PRIMARY KEY(repo_id,slug,version));
CREATE TABLE repository_stars (repo_id TEXT NOT NULL REFERENCES repositories(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY(repo_id,user_id));
CREATE TABLE repository_watches (repo_id TEXT NOT NULL REFERENCES repositories(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY(repo_id,user_id));
CREATE TABLE notifications (id INTEGER PRIMARY KEY AUTOINCREMENT, repo_id TEXT NOT NULL REFERENCES repositories(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, action TEXT NOT NULL, detail TEXT NOT NULL, read INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX notifications_user ON notifications(user_id,id);
CREATE TRIGGER wiki_insert_history AFTER INSERT ON wiki_pages BEGIN INSERT INTO wiki_history(repo_id,slug,version,title,body,author_id) VALUES(new.repo_id,new.slug,new.version,new.title,new.body,new.author_id); END;
CREATE TRIGGER wiki_update_history AFTER UPDATE ON wiki_pages BEGIN INSERT INTO wiki_history(repo_id,slug,version,title,body,author_id) VALUES(new.repo_id,new.slug,new.version,new.title,new.body,new.author_id); END;
CREATE TRIGGER audit_notify AFTER INSERT ON audit WHEN new.repo_id IS NOT NULL BEGIN INSERT INTO notifications(repo_id,user_id,action,detail) SELECT new.repo_id,w.user_id,new.action,new.detail FROM repository_watches w JOIN users u ON u.id=w.user_id WHERE w.repo_id=new.repo_id AND u.disabled=0 AND w.user_id IS NOT new.actor_id; END;
